// ✏️ 이 노드만 열어서 우리 회사 이벤트 값으로 바꾸면 바로 돌아갑니다.
// 금액은 모두 KRW 정수입니다.
// 인보이스·출장 예약/취소·정산 내역 어느 쪽이든 아래 모양으로만 맞추면 됩니다.
return [{
  json: {
    // 거래 당사자(에이전트) 식별자 — 자유 문자열
    buyer_id: 'agent_buyer_01',
    supplier_id: 'agent_supplier_42',

    // 사전 합의한 규칙 버전 (양쪽이 같아야 quote-lock 성립)
    buyer_version: '1.0',
    supplier_version: '1.0',

    // 사전 합의 조건 — 이 값들이 해시로 고정됩니다
    terms: {
      price_krw: 220000,
      currency: 'KRW',
      free_cancel_until: '2026-11-25T18:00:00+09:00',
      refund_ratio_on_cancel: 1.0,
      holdback_ratio: 0.10
    },

    // 정산 대조 입력
    tx_id: 'tx_20261121_0001',
    expected_amount_krw: 220000,
    actual_settled_krw: 180000,
    holdback_krw: 22000,
    // 'POST_TRADE_REFUND' (거래 후 환불/부분결제) 또는 'HALF_OPEN_TIMEOUT' (응답 없는 채 남은 건)
    event_type: 'POST_TRADE_REFUND'
  }
}];

// 입력 이벤트를 두 API 요청 본문으로 정규화하고, 서버가 거절할 값을 먼저 걸러냅니다.
// (전화·웹훅·수동 어느 경로로 들어와도 이 노드 뒤는 동일합니다.)
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const e = items[i].json || {};
  const terms = (e.terms && typeof e.terms === 'object') ? e.terms : {};

  const priceRaw = (e.price_krw !== undefined) ? e.price_krw : terms.price_krw;
  const price = Number(priceRaw);
  const expectedRaw = (e.expected_amount_krw !== undefined) ? e.expected_amount_krw : price;
  const expected = Number(expectedRaw);
  const actual = Number(e.actual_settled_krw);

  const ratioRaw = (terms.holdback_ratio !== undefined) ? terms.holdback_ratio : 0.1;
  const ratio = Number(ratioRaw);
  const holdback = (e.holdback_krw !== undefined && e.holdback_krw !== null && e.holdback_krw !== '')
    ? Number(e.holdback_krw)
    : Math.round(expected * (isFinite(ratio) ? ratio : 0.1));

  const missing = [];
  if (!e.buyer_id) missing.push('buyer_id');
  if (!e.supplier_id) missing.push('supplier_id');
  if (!e.tx_id) missing.push('tx_id');
  if (!isFinite(price)) missing.push('terms.price_krw');
  if (!isFinite(actual)) missing.push('actual_settled_krw');
  if (missing.length) {
    throw new Error('필수 값이 없습니다: ' + missing.join(', '));
  }

  const buyerVersion = String(e.buyer_version || '1.0');
  const supplierVersion = String(e.supplier_version || '1.0');
  if (buyerVersion !== supplierVersion) {
    throw new Error('buyer_version(' + buyerVersion + ') 과 supplier_version(' + supplierVersion + ') 이 다릅니다. 규칙 버전이 같아야 quote-lock 이 성립합니다.');
  }

  const eventType = (e.event_type === 'HALF_OPEN_TIMEOUT') ? 'HALF_OPEN_TIMEOUT' : 'POST_TRADE_REFUND';
  const idemKey = String(e.idempotency_key || ('idem_' + e.tx_id));

  out.push({ json: {
    quote_lock_body: {
      buyer_version: buyerVersion,
      supplier_version: supplierVersion,
      buyer_id: String(e.buyer_id),
      supplier_id: String(e.supplier_id),
      terms: terms
    },
    reconcile_body: {
      idempotency_key: idemKey,
      tx_id: String(e.tx_id),
      quote_hash: '',
      expected_amount_krw: Math.trunc(expected),
      actual_settled_krw: Math.trunc(actual),
      holdback_krw: Math.trunc(holdback),
      event_type: eventType
    },
    meta: {
      tx_id: String(e.tx_id),
      buyer_id: String(e.buyer_id),
      supplier_id: String(e.supplier_id),
      buyer_version: buyerVersion,
      price_krw: Math.trunc(price),
      free_cancel_until: terms.free_cancel_until || null,
      expected_amount_krw: Math.trunc(expected),
      actual_settled_krw: Math.trunc(actual),
      holdback_krw: Math.trunc(holdback),
      event_type: eventType,
      idempotency_key: idemKey,
      received_at: new Date().toISOString()
    }
  }});
}
return out;

// 402(결제 필요)·409(버전 불일치)·422(본문 형식)를 사람이 읽는 형태로 풀어 알림 문구를 만듭니다.
function decodeBase64Json(value) {
  try {
    let text = '';
    if (typeof Buffer !== 'undefined') {
      text = Buffer.from(value, 'base64').toString('utf8');
    } else if (typeof atob === 'function') {
      const bin = atob(value);
      const bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      text = new TextDecoder('utf-8').decode(bytes);
    } else {
      return null;
    }
    return JSON.parse(text);
  } catch (err) {
    return null;
  }
}

const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const res = items[i].json || {};
  const body = res.body || {};
  const headers = res.headers || {};
  const raw = headers['payment-required'] || headers['PAYMENT-REQUIRED'];
  const required = raw ? decodeBase64Json(raw) : null;
  const accept = (required && required.accepts && required.accepts.length) ? required.accepts[0] : null;

  let reason = 'HTTP ' + res.statusCode;
  if (body && body.error) reason = String(body.error);
  if (body && body.detail && body.detail.error) reason = String(body.detail.error);
  if (required && required.error) reason = String(required.error);

  const amountUsd = accept ? (Number(accept.amount) / 1000000).toFixed(2) : null;

  const lines = [
    'Reciprocal Ruler · quote-lock 실패 [' + res.statusCode + ' ' + reason + ']'
  ];
  if (accept) {
    lines.push('- 결제 요구: ' + amountUsd + ' USDC on ' + accept.network + ' → ' + accept.payTo);
  }
  if (res.statusCode === 402) {
    lines.push('- 원인: x402 유료 엔드포인트입니다. 결제 서명(PAYMENT-SIGNATURE)이 없거나 지갑 잔액이 부족합니다.');
    lines.push('- 조치: 결제 릴레이(x402 payer)를 거치도록 이 HTTP 노드 URL을 바꾸거나, Base USDC 지갑으로 서명한 헤더를 붙여 다시 보내세요.');
  }
  if (res.statusCode === 409) {
    lines.push('- 원인: 두 에이전트의 규칙 버전이 다릅니다. buyer_version 과 supplier_version 을 맞추세요.');
  }
  if (res.statusCode === 422) {
    lines.push('- 원인: 요청 본문 형식 오류입니다. 필드 이름·타입(int/string)을 확인하세요.');
  }
  if (res.statusCode >= 500) {
    lines.push('- 원인: 서버 오류입니다. 무료 호스팅 콜드 스타트(수십 초)일 수 있으니 잠시 뒤 재시도하세요.');
  }

  out.push({ json: {
    stage: 'quote-lock',
    status_code: res.statusCode,
    reason: reason,
    payment_required: accept ? {
      network: accept.network,
      asset: accept.asset,
      amount_atomic: accept.amount,
      amount_usd: amountUsd,
      pay_to: accept.payTo,
      max_timeout_seconds: accept.maxTimeoutSeconds
    } : null,
    alert_text: lines.join('\n')
  }});
}
return out;

// quote-lock 응답에서 quote_hash 를 꺼내 reconcile 본문에 붙입니다.
// 결제가 성사됐다면 PAYMENT-RESPONSE 헤더에 정산 영수증이 함께 옵니다.
function decodeBase64Json(value) {
  try {
    let text = '';
    if (typeof Buffer !== 'undefined') {
      text = Buffer.from(value, 'base64').toString('utf8');
    } else if (typeof atob === 'function') {
      const bin = atob(value);
      const bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      text = new TextDecoder('utf-8').decode(bytes);
    } else {
      return null;
    }
    return JSON.parse(text);
  } catch (err) {
    return null;
  }
}

const inputs = $input.all();
const normItems = $('2. Normalize & Validate').all();
const out = [];

for (let i = 0; i < inputs.length; i++) {
  const res = inputs[i].json || {};
  const body = res.body || {};
  const headers = res.headers || {};
  const norm = ((normItems[i] || {}).json) || {};
  const meta = norm.meta || {};
  const base = norm.reconcile_body || {};

  const quoteHash = body.quote_hash || '';
  const reconcileBody = Object.assign({}, base, { quote_hash: quoteHash });

  const receiptHeader = headers['payment-response'] || headers['PAYMENT-RESPONSE'];
  const receipt = receiptHeader ? decodeBase64Json(receiptHeader) : null;

  out.push({ json: {
    quote_lock: {
      status: body.status || null,
      quote_hash: quoteHash,
      rule_version: body.rule_version || null,
      locked_at: body.locked_at || null
    },
    payment_receipt: receipt,
    reconcile_body: reconcileBody,
    meta: meta
  }});
}

if (out.length === 0) {
  throw new Error('quote-lock 응답이 비어 있습니다.');
}
if (!out[0].json.quote_lock.quote_hash) {
  throw new Error('quote-lock 응답에 quote_hash 가 없습니다. 3c 노드의 오류 내용을 확인하세요.');
}
return out;

// reconcile 실패(402/422/5xx)를 풀어 알림 문구를 만듭니다.
function decodeBase64Json(value) {
  try {
    let text = '';
    if (typeof Buffer !== 'undefined') {
      text = Buffer.from(value, 'base64').toString('utf8');
    } else if (typeof atob === 'function') {
      const bin = atob(value);
      const bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      text = new TextDecoder('utf-8').decode(bytes);
    } else {
      return null;
    }
    return JSON.parse(text);
  } catch (err) {
    return null;
  }
}

const items = $input.all();
const prevItems = $('4. Attach quote_hash').all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const res = items[i].json || {};
  const body = res.body || {};
  const headers = res.headers || {};
  const prev = ((prevItems[i] || {}).json) || {};
  const meta = prev.meta || {};
  const raw = headers['payment-required'] || headers['PAYMENT-REQUIRED'];
  const required = raw ? decodeBase64Json(raw) : null;
  const accept = (required && required.accepts && required.accepts.length) ? required.accepts[0] : null;

  let reason = 'HTTP ' + res.statusCode;
  if (body && body.error) reason = String(body.error);
  if (body && body.detail && body.detail.error) reason = String(body.detail.error);
  if (body && body.detail && !body.detail.error && typeof body.detail === 'string') reason = body.detail;
  if (required && required.error) reason = String(required.error);

  const amountUsd = accept ? (Number(accept.amount) / 1000000).toFixed(2) : null;

  const lines = [
    'Reciprocal Ruler · reconcile 실패 [' + res.statusCode + ' ' + reason + ']',
    '- tx_id: ' + (meta.tx_id || '(알 수 없음)') + ' / 기대금액: ' + meta.expected_amount_krw + ' KRW'
  ];
  if (accept) {
    lines.push('- 결제 요구: ' + amountUsd + ' USDC on ' + accept.network + ' → ' + accept.payTo);
  }
  if (res.statusCode === 402) {
    lines.push('- 원인: 결제 서명이 없거나 지갑 잔액 부족. 같은 본문으로 결제 포함 재요청이 필요합니다.');
  }
  if (res.statusCode === 422) {
    lines.push('- 원인: 본문 형식 오류. quote_hash 가 quote-lock 응답값인지, 금액이 정수인지 확인하세요.');
  }
  if (res.statusCode >= 500) {
    lines.push('- 원인: 서버 오류(콜드 스타트 가능). 잠시 뒤 같은 idempotency_key 로 재시도하세요.');
  }

  out.push({ json: {
    stage: 'reconcile',
    status_code: res.statusCode,
    reason: reason,
    tx_id: meta.tx_id || null,
    alert_text: lines.join('\n')
  }});
}
return out;

// reconcile 응답 상태를 판정으로 바꿉니다.
//   SETTLED_OK              → 일치(MATCHED)                    → 감사 로그
//   COMPENSATED             → 부분결제·환불, 유보금으로 보전   → 알림
//   PENDING_RECONCILIATION  → 미지급(대조 대기)                → 알림
function decodeBase64Json(value) {
  try {
    let text = '';
    if (typeof Buffer !== 'undefined') {
      text = Buffer.from(value, 'base64').toString('utf8');
    } else if (typeof atob === 'function') {
      const bin = atob(value);
      const bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      text = new TextDecoder('utf-8').decode(bytes);
    } else {
      return null;
    }
    return JSON.parse(text);
  } catch (err) {
    return null;
  }
}

// 3자리 콤마 (로케일과 무관하게 같은 문구가 나오도록 직접 만든다)
function fmtKrw(n) {
  const v = Math.round(Number(n) || 0);
  return String(v).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

const STATES = {
  SETTLED_OK: { verdict: 'MATCHED', action: 'audit', label: '정상 일치' },
  COMPENSATED: { verdict: 'EXCEPTION', action: 'alert', label: '부분결제 · 유보금 보전' },
  PENDING_RECONCILIATION: { verdict: 'PENDING', action: 'alert', label: '미지급 · 대조 대기' }
};

const items = $input.all();
const prevItems = $('4. Attach quote_hash').all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const res = items[i].json || {};
  const body = res.body || {};
  const headers = res.headers || {};
  const prev = ((prevItems[i] || {}).json) || {};
  const meta = prev.meta || {};
  const quote = prev.quote_lock || {};

  const state = body.status || 'UNKNOWN';
  const rule = STATES[state] || { verdict: 'UNKNOWN', action: 'alert', label: '알 수 없는 상태' };

  let receipt = prev.payment_receipt || null;
  const receiptHeader = headers['payment-response'] || headers['PAYMENT-RESPONSE'];
  if (receiptHeader) {
    const decoded = decodeBase64Json(receiptHeader);
    if (decoded) receipt = decoded;
  }

  const expected = Number(meta.expected_amount_krw || 0);
  const actual = Number(meta.actual_settled_krw || 0);
  const shortfall = expected - actual;
  const compensated = Number(body.compensated_krw || 0);
  const uncovered = Number(body.uncovered_krw || 0);

  const record = {
    recorded_at: new Date().toISOString(),
    tx_id: body.tx_id || meta.tx_id || null,
    idempotency_key: meta.idempotency_key || null,
    quote_hash: quote.quote_hash || null,
    rule_version: quote.rule_version || null,
    buyer_id: meta.buyer_id || null,
    supplier_id: meta.supplier_id || null,
    event_type: meta.event_type || null,
    expected_amount_krw: expected,
    actual_settled_krw: actual,
    shortfall_krw: shortfall > 0 ? shortfall : 0,
    holdback_krw: Number(meta.holdback_krw || 0),
    state: state,
    verdict: rule.verdict,
    action: rule.action,
    compensated_krw: compensated,
    uncovered_krw: uncovered,
    credit_delta: Number(body.credit_delta || 0),
    idempotent_replay: body.idempotent_replay === true,
    payment_payer: receipt ? (receipt.payer || null) : null,
    payment_tx: receipt ? (receipt.transaction || null) : null,
    payment_network: receipt ? (receipt.network || null) : null
  };

  const lines = [];
  if (rule.verdict === 'MATCHED') {
    lines.push('Reciprocal Ruler · 정산 일치');
  } else {
    lines.push('Reciprocal Ruler · 정산 예외 — ' + rule.label);
  }
  lines.push('- tx_id: ' + record.tx_id);
  lines.push('- 상태: ' + state + (record.idempotent_replay ? ' (멱등 재생)' : ''));
  lines.push('- 기대 / 실제: ' + fmtKrw(expected) + ' / ' + fmtKrw(actual) + ' KRW');
  if (shortfall > 0) lines.push('- 부족액: ' + fmtKrw(shortfall) + ' KRW');
  lines.push('- 유보금 보전: ' + fmtKrw(compensated) + ' KRW / 미보전: ' + fmtKrw(uncovered) + ' KRW');
  lines.push('- 신용 변화(credit_delta): ' + record.credit_delta);
  if (record.payment_tx) lines.push('- 결제 영수증 tx: ' + record.payment_tx);

  const merged = Object.assign({}, record, { alert_text: lines.join('\n') });
  out.push({ json: merged });
}
return out;

// 정상 일치 건을 append-only 감사 로그 한 줄로 만듭니다.
// audit_line 은 탭 구분 — Google Sheets / Data Table / 자체 로그에 그대로 append 하세요.
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const r = items[i].json || {};
  const cols = [
    r.recorded_at, r.tx_id, r.quote_hash, r.rule_version,
    r.buyer_id, r.supplier_id, r.event_type,
    r.expected_amount_krw, r.actual_settled_krw, r.shortfall_krw,
    r.state, r.compensated_krw, r.uncovered_krw, r.credit_delta,
    r.payment_tx || ''
  ];
  out.push({ json: Object.assign({}, r, {
    audit_line: cols.join('\t'),
    audit_status: 'APPEND'
  }) });
}
return out;
